import React from 'react';
import { usePageI18n } from '../../i18n';
import FamilyIndexPage from '../../components/FamilyIndexPage';

export default function UseCasesIndex(pageContext) {
  // 🔴 用 usePageI18n 而非 pageContext?.locale：后者在 src/pages 文件路由下
  //    顶层可能没有 locale，SEO 的 hrefLang 会回退 en ⇒ og:image:alt 残留英文。
  const { locale } = usePageI18n(pageContext);
  return <FamilyIndexPage familyKey="use-cases" locale={locale} />;
}
